try {
  let menu = [];
  try {
    const menuJson = $('Extrai Campos').item.json?.menu_json;
    menu = menuJson ? JSON.parse(menuJson) : [];
  } catch (e) {
    return { found: false, message: 'Erro ao carregar cardápio' };
  }

  const query = String($input.item.json?.query || '').toLowerCase();

  const results = menu.filter(p => 
    (p.name && p.name.toLowerCase().includes(query)) || 
    (p.description && p.description.toLowerCase().includes(query)) ||
    (p.category && p.category.toLowerCase().includes(query))
  );

  if (results.length === 0) {
    return { found: false, message: 'Nenhum produto encontrado para: ' + query };
  }

  const formatted = results.slice(0, 5).map(p => 
    `• ${p.name} - R$ ${p.price.toFixed(2)}${p.description ? ' (' + p.description.substring(0, 50) + ')' : ''}`
  ).join('\n');

  return {
    found: true,
    count: results.length,
    products: results.slice(0, 5),
    formatted: formatted
  };
} catch (err) {
  return { found: false, message: 'Erro interno: ' + String(err.message || err) };
}

