try {
  let menu = [];
  let extraiCampos = {};
  try {
    extraiCampos = $('Extrai Campos').item.json || {};
    const menuJson = extraiCampos.menu_json;
    menu = menuJson ? JSON.parse(menuJson) : [];
  } catch (e) {
    return { success: false, message: 'Erro ao carregar cardápio' };
  }

  const productName = String($input.item.json?.product_name || '').toLowerCase();
  const product = menu.find(p => p.name && p.name.toLowerCase().includes(productName));

  if (!product || !product.image_url) {
    return { success: false, message: 'Produto não encontrado ou sem foto: ' + productName };
  }

  const supabaseUrl = $env.SUPABASE_URL;
  const supabaseKey = $env.SUPABASE_ANON_KEY;

  const response = await fetch(supabaseUrl + '/functions/v1/whatsapp-send-media', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + supabaseKey
    },
    body: JSON.stringify({
      instance_name: extraiCampos.instance_name || '',
      phone: extraiCampos.phone || '',
      media_url: product.image_url,
      media_type: 'image',
      caption: `📸 *${product.name}*\n💰 R$ ${product.price.toFixed(2)}\n\n${product.description || ''}`
    })
  });

  const result = await response.json();
  return {
    success: result.success,
    product: product.name,
    price: product.price,
    message: result.success ? 'Foto enviada!' : 'Erro ao enviar foto'
  };
} catch (err) {
  return { success: false, message: 'Erro interno: ' + String(err.message || err) };
}

